\label{1.2} \emph{ Let $M$ be a finite $R$--module
	and $I$ be an ideal of $R$. When are $ \operatorname{H}^{i}_{I}(M)$ $I$--cofinite for all $i\geq
	0$?}

\label{haj1}
	Let $M$ be an  $R$-module. Then the following statements are equivalent:
	\begin{itemize}
		\item[(i)] $M$ is weakly Artinian.
		\item[(ii)] $\operatorname{Ass}_R(M)$ consists of finitely many maximal ideals.
		\item[(iii)] $\operatorname{Supp}_R(M)$ consists of finitely many maximal ideals.
		\item[(iv)] $\operatorname{Ass}_R(M)=\operatorname{Supp}_R(M)$ and it  consists of finitely many maximal ideals.
		\item[(v)] $M$ is weakly Laskerin and $\operatorname{Ass}_R(M)\subseteq \operatorname{Max}(R)$.

	\end{itemize}

\label{max}
	Let $I$ be an ideal of a Noetherian ring $R$ and $M$ be an  $R$-module such that $\operatorname{Supp}_R(M)\subseteq \operatorname{Max}(R)$. Then the
	following statements are equivalent:
	\begin{itemize}
		\item[(i)] $M$ is $I$-$ETH$-weakly cofinite.
		\item[(ii)] The $R$-module $\operatorname{Hom}_R(R/I,M)$ is weakly Laskerian.
	\end{itemize}

\label{third}
	If  $0\longrightarrow N\longrightarrow L\longrightarrow T\longrightarrow 0$ is exact and two of the modules in the sequence are $I$-$ETH$-weakly cofinite, then so is the third
	one.

\label{FD0}
 Let $I$ be an ideal of a Noetherian ring $R$ and $M$ be an  ${\rm FD_{\leq0}}$ {\rm{(}}or minimax{\rm{)}} $R$-module.
  Then the
 following statements are equivalent:
 \begin{itemize}
 \item[(i)] $M$ is $I$-$ETH$-weakly cofinite.
\item[(ii)] The $R$-module $\operatorname{Hom}_R(R/I,M)$ is weakly Laskerian.
 \end{itemize}

\label {asli}
Let $R$ be a Noetherian ring and $I$ be an ideal of $R$ {\rm (}not necessary
dimension one{\rm )}. Let $M$ be a non-zero $R$-module {\rm (}not necessary
$I$-torsion{\rm )} such that  $\dim M \leq 1$. Then the following conditions are
equivalent:
 \begin{itemize}
 \item[(i)] $M$ is $I$-$ETH$-weakly cofinite.
 \item[(ii)] $\operatorname{H}^{i}_{I}(M)$ are $I$-weakly cofinite for all $i$.
\item[(iii)] The $R$-modules $\operatorname{Hom}_R(R/I,M)$ and $\operatorname{Ext}^{1}_R(R/I,M)$ are weakly Laskerian.
 \end{itemize}

\label{torext}
 Let $R$ be a Noetherian ring and $I$ a proper ideal of $R$. Let  $M$ is a non-zero $I$-$ETH$-weakly cofinite  ${\rm FD_{\leq1}}$ ~ $R$-module. Then, the R-modules ${\rm Ext}^{i}_R(N,M)$ and ${\rm Tor}^R_{i}(N,M)$ are $I$-$ETH$-weakly cofinite  ${\rm
FD_{\leq1}}$~ $R$-modules, for all finitely generated $R$-modules $N$ and all integers $ i \geq 0$.
